import { useState } from 'react';
import './styles.css';

export type Folder = {
  id: string;
  name: string;
  children: Folder[];
};

export type Props = {
  folders: Folder[];
  onNavigate: (path: string[]) => void;
};

export function Component({ folders, onNavigate }: Props) {
  const [path, setPath] = useState<string[]>([]);
  const names: string[] = [];
  let currentFolders = folders;

  for (const id of path) {
    const folder = currentFolders.find((candidate) => candidate.id === id);
    if (!folder) break;
    names.push(folder.name);
    currentFolders = folder.children;
  }

  return (
    <div className="folder-browser" data-testid="panel">
      <output aria-label="Current path">{'/' + names.join('/')}</output>
      <button
        type="button"
        disabled={path.length === 0}
        onClick={() => {
          if (path.length === 0) return;
          const nextPath = path.slice(0, -1);
          setPath(nextPath);
          onNavigate(nextPath);
        }}
      >
        Back
      </button>
      <ul aria-label="Folders">
        {currentFolders.map((folder) => (
          <li key={folder.id}>
            <button
              type="button"
              onClick={() => {
                const nextPath = [...path, folder.id];
                setPath(nextPath);
                onNavigate(nextPath);
              }}
            >
              Enter {folder.name}
            </button>
          </li>
        ))}
      </ul>
      {currentFolders.length === 0 && <p role="status">No folders</p>}
    </div>
  );
}

